import re
import statistics
import time
from pathlib import Path

from sqlalchemy import text

INDEX_NAME_PATTERN = re.compile(r"CREATE INDEX IF NOT EXISTS (\w+)", re.IGNORECASE)
TABLE_PATTERN = re.compile(r"\bON olist\.(\w+)", re.IGNORECASE)
INDEX_FILE_HEADER = (
    "-- Generated by solution.ipynb (index decision section). "
    "Only indexes with plan evidence belong here.\n"
)


def read_index_statements(sql_path):
    statements = {}
    for part in Path(sql_path).read_text(encoding="utf-8").split(";"):
        match = INDEX_NAME_PATTERN.search(part)
        if match:
            statements[match.group(1)] = part[match.start():].strip()
    return statements


def table_of_statement(statement):
    return TABLE_PATTERN.search(statement).group(1)


def write_index_file(sql_path, statements, kept_names):
    body = "\n\n".join(statements[name] + ";" for name in kept_names)
    content = INDEX_FILE_HEADER + ("\n" + body + "\n" if body else "")
    Path(sql_path).write_text(content, encoding="utf-8")


def create_index(engine, statement):
    with engine.begin() as connection:
        connection.exec_driver_sql(statement)


def drop_index(engine, index_name):
    quoted_name = engine.dialect.identifier_preparer.quote(index_name)
    with engine.begin() as connection:
        connection.exec_driver_sql(f"DROP INDEX IF EXISTS olist.{quoted_name}")


def drop_indexes(engine, index_names):
    for index_name in index_names:
        drop_index(engine, index_name)


def relation_size_bytes(engine, qualified_name):
    sql = text("SELECT pg_relation_size(to_regclass(:name))")
    with engine.connect() as connection:
        return connection.execute(sql, {"name": qualified_name}).scalar_one()


def total_index_size_bytes(engine, qualified_table):
    sql = text("SELECT pg_indexes_size(to_regclass(:name))")
    with engine.connect() as connection:
        return connection.execute(sql, {"name": qualified_table}).scalar_one()


def make_lab_statement(statement, table_name, index_name):
    lab_statement = statement.replace(f"olist.{table_name}", "olist.insert_lab")
    return lab_statement.replace(index_name, f"{index_name}_lab", 1)


def time_bulk_insert(engine, table_name, lab_statements):
    quoted_table = engine.dialect.identifier_preparer.quote(table_name)
    with engine.begin() as connection:
        connection.exec_driver_sql("DROP TABLE IF EXISTS olist.insert_lab")
        connection.exec_driver_sql(
            f"CREATE TABLE olist.insert_lab "
            f"(LIKE olist.{quoted_table} INCLUDING DEFAULTS INCLUDING INDEXES)"
        )
        for statement in lab_statements:
            connection.exec_driver_sql(statement)
        started = time.perf_counter()
        connection.exec_driver_sql(
            f"INSERT INTO olist.insert_lab SELECT * FROM olist.{quoted_table}"
        )
        elapsed_ms = (time.perf_counter() - started) * 1000
        connection.exec_driver_sql("DROP TABLE olist.insert_lab")
    return elapsed_ms


def measure_insert_cost(engine, table_name, statements_by_name, repeats=3):
    lab_statements = [
        make_lab_statement(statement, table_name, index_name)
        for index_name, statement in statements_by_name.items()
    ]
    baseline_runs = [time_bulk_insert(engine, table_name, []) for _ in range(repeats)]
    indexed_runs = [time_bulk_insert(engine, table_name, lab_statements) for _ in range(repeats)]
    baseline_ms = statistics.median(baseline_runs)
    indexed_ms = statistics.median(indexed_runs)
    return {
        "table": table_name,
        "indexes": ", ".join(statements_by_name),
        "pk_only_ms": round(baseline_ms, 1),
        "with_indexes_ms": round(indexed_ms, 1),
        "slowdown_percent": round((indexed_ms - baseline_ms) / baseline_ms * 100, 1),
    }
